namespace EduCenterManagement.ViewModels.ParentChildren;
public sealed class AttendancePageViewModel { public int StudentId {get;init;} public string StudentName {get;init;}=""; public IReadOnlyList<AttendanceRowViewModel> Items {get;init;}=Array.Empty<AttendanceRowViewModel>(); public IReadOnlyList<AttendanceClassOptionViewModel> Classes {get;init;}=Array.Empty<AttendanceClassOptionViewModel>(); public int? ClassId {get;init;} public int Page {get;init;} public int TotalPages {get;init;} public int Present {get;init;} public int Absent {get;init;} public decimal AttendanceRate => Present+Absent==0?0:Math.Round(Present*100m/(Present+Absent),1); }
public sealed class AttendanceRowViewModel { public DateOnly Date {get;init;} public string Subject {get;init;}=""; public string ClassName {get;init;}=""; public int SessionNumber {get;init;} public string Status {get;init;}=""; public string? Note {get;init;} }
public sealed class AttendanceClassOptionViewModel { public int Id {get;init;} public string Name {get;init;}=""; }
